import{_ as t,a as o,b as a,c as i,d as n}from"./chunks/power-button.B-WxPnfE.js";import{_ as r,o as s,c as l,a5 as c}from"./chunks/framework.CcrBcQWS.js";const P=JSON.parse('{"title":"1. Initial Pose & Power On","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"guides/common/initial-pose.md","filePath":"guides/common/initial-pose.md","lastUpdated":1787021357000}'),h={name:"guides/common/initial-pose.md"};function p(d,e,u,f,g,m){return s(),l("div",null,[...e[0]||(e[0]=[c('<h1 id="_1-initial-pose-power-on" tabindex="-1">1. Initial Pose &amp; Power On <a class="header-anchor" href="#_1-initial-pose-power-on" aria-label="Permalink to &quot;1. Initial Pose &amp; Power On&quot;">​</a></h1><p><strong>Goal:</strong> Place the robot in the correct initial pose on a flat surface, then power it on.</p><div class="sb sb-required"><div class="sb-icon"><span class="sb-book" aria-hidden="true">📖</span></div><div class="sb-content"><p class="custom-block-title">REQUIRED READING</p><p>Before operating the robot, read the <a href="/RBQ/nightly/manual/safety/general-safety-warning-precautions">General Safety Guidelines</a> and the <a href="/RBQ/nightly/manual/safety/indications">Safety Indications</a>.</p></div></div><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A flat, stable floor with sufficient open space (minimum 2 m radius clearance around the robot)</li><li>The robot battery is charged</li><li>No people or animals within 2 m of the robot</li></ul><h2 id="setting-the-initial-pose" tabindex="-1">Setting the Initial Pose <a class="header-anchor" href="#setting-the-initial-pose" aria-label="Permalink to &quot;Setting the Initial Pose&quot;">​</a></h2><p>Place the robot on the floor so that all feet and knees contact the ground simultaneously.</p><figure><img src="'+t+'" alt="RBQ10 correct initial pose overview"><figcaption style="text-align:center;">[ RBQ10 Initial Pose ]</figcaption></figure><h3 id="step-1-choose-a-flat-surface" tabindex="-1">Step 1. Choose a flat surface <a class="header-anchor" href="#step-1-choose-a-flat-surface" aria-label="Permalink to &quot;Step 1. Choose a flat surface&quot;">​</a></h3><p>Place the robot on a level floor. Uneven surfaces can cause Auto Start to fail.</p><figure><img src="'+o+'" alt="Flat surface requirement"></figure><h3 id="step-2-fully-fold-the-knee-joints" tabindex="-1">Step 2. Fully fold the knee joints <a class="header-anchor" href="#step-2-fully-fold-the-knee-joints" aria-label="Permalink to &quot;Step 2. Fully fold the knee joints&quot;">​</a></h3><p>Fold all four knee joints completely so the knee pads are close to the ground.</p><figure><img src="'+a+'" alt="Fold knee joints"></figure><h3 id="step-3-set-all-three-ground-contact-points" tabindex="-1">Step 3. Set all three ground contact points <a class="header-anchor" href="#step-3-set-all-three-ground-contact-points" aria-label="Permalink to &quot;Step 3. Set all three ground contact points&quot;">​</a></h3><p>Rotate the hip pitch and roll joints until <strong>three points per leg</strong> contact the floor: the <strong>body bumper</strong>, the <strong>knee joint</strong>, and the <strong>foot</strong>.</p><figure><img src="'+i+'" alt="Three ground contact points"></figure><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">WARNING</p><p>If the initial pose is incorrect, Auto Start will fail and the robot may fall unexpectedly. Always confirm all contact points before powering on.</p></div></div><h2 id="power-on" tabindex="-1">Power On <a class="header-anchor" href="#power-on" aria-label="Permalink to &quot;Power On&quot;">​</a></h2><figure style="text-align:center;"><img src="'+n+'" alt="Power button" style="width:300px;"></figure><ol><li>Press the <strong>Power Button</strong> on the robot body.</li><li>Confirm the <strong>red indicator</strong> light on the button turns on.</li><li>Listen for the <strong>double-beep</strong> sound — this confirms the boot sequence has started.</li></ol><p>The robot will take about 30–60 seconds to fully initialize. Do not attempt to move the robot during this time.</p><h2 id="next-step" tabindex="-1">Next Step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next Step&quot;">​</a></h2><p>Once the robot is on and initialized, proceed to connect the controller and Wi-Fi:</p><p><strong><a href="/RBQ/nightly/guides/common/controller-wifi-connect.html">→ 2. Controller &amp; Wi-Fi Connection</a></strong></p>',25)])])}const y=r(h,[["render",p]]);export{P as __pageData,y as default};
